"""The config file: one file, every key optional, generated by ``bioguard init``.

A user who never opens ``bioguard.yaml`` must still get a correct run, so
every default here is one that works. The three named policies differ only
in how findings map to verdicts -- the layers themselves are the same
code -- which keeps "what did it check" separate from "how strict was it".
"""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml

from .record import Access, Verdict

#: Layers a brand-new config switches on, by corpus modality. Both defence
#: families are present for cells on purpose: ``recompute`` covers
#: synthesised geometry and nothing else, ``dedup``/``label_consistency``
#: cover genuine vectors with forged labels and nothing else. Enabling one
#: family ships a hole.
DEFAULT_LAYERS: dict[str, list[str]] = {
    "cell": [
        "qc_align", "qc_counts", "recompute", "label_consistency", "dedup",
        "idx_meta", "manifest_index", "manifest_label", "hub", "duplicate_cluster",
    ],
    "text-protein": [
        "crossmodal_maps", "crossmodal_agreement", "text_nearduplicate",
        "text_instruction", "text_fluency", "fragment_outlier", "hub",
        "idx_meta", "manifest_index", "manifest_label",
    ],
    # The generic list is every modality-neutral layer. Enabling one the corpus
    # cannot feed is harmless -- the builder skips it with a plain reason in the
    # report -- whereas omitting one silently removes a defence.
    "generic": [
        "qc_align", "qc_counts", "recompute", "label_consistency", "dedup",
        "idx_meta", "manifest_index", "manifest_label", "hub", "duplicate_cluster",
    ],
}

POLICIES = ("permissive", "balanced", "strict")


@dataclass
class LayerConfig:
    enabled: bool = True
    verdict: str | None = None
    params: dict[str, Any] = field(default_factory=dict)

    @classmethod
    def parse(cls, raw: Any) -> LayerConfig:
        if isinstance(raw, bool):
            return cls(enabled=raw)
        if not isinstance(raw, dict):
            raise TypeError(f"a layer config must be a mapping or a bool, got {type(raw)}")
        raw = dict(raw)
        return cls(
            enabled=bool(raw.pop("enabled", True)),
            verdict=raw.pop("verdict", None),
            params=raw,
        )

    def to_dict(self) -> dict[str, Any]:
        out: dict[str, Any] = {"enabled": self.enabled}
        if self.verdict:
            out["verdict"] = self.verdict
        out.update(self.params)
        return out


@dataclass
class VoteConfig:
    """Query-time policy. These layers have no ingest-time form."""

    k: int = 50
    weight: str = "uniform"
    weight_temp: float = 0.01
    abstain: bool = False
    abstain_min_margin: float = 0.0
    donor_cap: int = 0
    label_consistency: bool = False
    recompute: bool = False
    seasoning_days: int = 0
    dedup_tau: float = 0.0

    def to_dict(self) -> dict[str, Any]:
        return dict(self.__dict__)


@dataclass
class GuardConfig:
    """Everything one run needs."""

    path: Path = Path(".")
    adapter: str | None = None
    adapter_options: dict[str, Any] = field(default_factory=dict)
    access: list[Access] = field(default_factory=lambda: [Access.INSERT, Access.OVERWRITE])
    budget: float = 0.05
    policy: str = "balanced"
    layers: dict[str, LayerConfig] = field(default_factory=dict)
    vote: VoteConfig = field(default_factory=VoteConfig)
    manifest_path: Path = Path("bioguard_manifest.json")
    verify_on_scan: bool = True
    sample: int | None = 200_000
    since: str | None = None
    seed: int = 0
    report_dir: Path = Path("bioguard_reports")
    report_formats: list[str] = field(default_factory=lambda: ["html", "json"])
    baseline_path: Path = Path("baseline.json")
    quarantine_dir: Path = Path("quarantine")

    # -- io --------------------------------------------------------------

    @classmethod
    def load(cls, path: str | Path) -> GuardConfig:
        path = Path(path)
        raw = yaml.safe_load(path.read_text()) or {}
        cfg = cls.from_dict(raw, base=path.parent)
        return cfg

    @classmethod
    def from_dict(cls, raw: dict[str, Any], base: Path | None = None) -> GuardConfig:
        base = base or Path(".")
        corpus = raw.get("corpus", {}) or {}
        options = {k: v for k, v in corpus.items() if k not in ("adapter", "path")}
        policy = str(raw.get("policy", "balanced"))
        if policy not in POLICIES:
            raise ValueError(f"unknown policy {policy!r}; expected one of {POLICIES}")
        scan = raw.get("scan", {}) or {}
        report = raw.get("report", {}) or {}
        manifest = raw.get("manifest", {}) or {}
        vote_raw = raw.get("vote", {}) or {}
        cfg = cls(
            path=_resolve(base, corpus.get("path", ".")),
            adapter=corpus.get("adapter"),
            adapter_options=options,
            access=[Access(a) for a in raw.get("access", ["insert", "overwrite"])],
            budget=float(raw.get("budget", 0.05)),
            policy=policy,
            layers={k: LayerConfig.parse(v) for k, v in (raw.get("layers") or {}).items()},
            vote=VoteConfig(**vote_raw),
            manifest_path=_resolve(base, manifest.get("path", "bioguard_manifest.json")),
            verify_on_scan=bool(manifest.get("verify_on_scan", True)),
            sample=scan.get("sample", 200_000),
            since=scan.get("since"),
            seed=int(raw.get("seed", 0)),
            report_dir=_resolve(base, report.get("dir", "bioguard_reports")),
            report_formats=list(report.get("formats", ["html", "json"])),
            baseline_path=_resolve(base, raw.get("baseline", "baseline.json")),
            quarantine_dir=_resolve(base, (raw.get("quarantine") or {}).get(
                "dir", "quarantine")),
        )
        return cfg

    def to_dict(self) -> dict[str, Any]:
        return {
            "corpus": {"adapter": self.adapter, "path": str(self.path),
                       **self.adapter_options},
            "access": [a.value for a in self.access],
            "budget": self.budget,
            "policy": self.policy,
            "layers": {k: v.to_dict() for k, v in self.layers.items()},
            "vote": self.vote.to_dict(),
            "manifest": {"path": str(self.manifest_path),
                         "verify_on_scan": self.verify_on_scan},
            "scan": {"sample": self.sample, "since": self.since},
            "report": {"dir": str(self.report_dir), "formats": self.report_formats},
            "baseline": str(self.baseline_path),
            "quarantine": {"dir": str(self.quarantine_dir)},
            "seed": self.seed,
        }

    def save(self, path: str | Path) -> Path:
        path = Path(path)
        path.write_text(render_yaml(self))
        return path

    @classmethod
    def for_corpus(cls, path: str | Path, adapter: str | None = None) -> GuardConfig:
        """Defaults for a corpus opened without a config file.

        The baseline and the manifest describe *this* corpus, so they live
        beside it: `bioguard calibrate <corpus>` then `bioguard check
        --corpus <corpus>` has to work from any working directory, which is
        the whole three-commands-and-a-report promise. Reports and quarantine
        lists are the user's output, so they stay under the working directory.
        """
        path = Path(path)
        return cls(
            path=path,
            adapter=adapter,
            baseline_path=path / "baseline.json",
            manifest_path=path / "bioguard_manifest.json",
        )

    # -- policy ----------------------------------------------------------

    def verdict_for(self, layer_name: str, default: Verdict) -> Verdict:
        """How a firing of this layer is treated, after the policy is applied."""
        override = self.layers.get(layer_name, LayerConfig()).verdict
        if override:
            return Verdict(override)
        if self.policy == "permissive":
            # only structural integrity stops anything
            if default is Verdict.REJECT and layer_name in _STRUCTURAL:
                return Verdict.REJECT
            return Verdict.FLAG
        if self.policy == "strict":
            return Verdict.QUARANTINE if default is Verdict.FLAG else default
        return default


#: Layers whose findings are facts about the corpus files rather than
#: judgements about a record. Even the permissive policy stops on these.
_STRUCTURAL = {"idx_meta", "crossmodal_maps", "qc_align", "manifest_index", "manifest_label"}


def _resolve(base: Path, value: Any) -> Path:
    p = Path(str(value))
    return p if p.is_absolute() else (base / p)


def default_layers_for(modality: str) -> list[str]:
    return list(DEFAULT_LAYERS.get(modality, DEFAULT_LAYERS["generic"]))


def render_yaml(cfg: GuardConfig) -> str:
    """A commented config, because a generated file nobody can read is a bug."""
    body = str(yaml.safe_dump(cfg.to_dict(), sort_keys=False, default_flow_style=False))
    header = (
        "# BioRAG-Guard configuration. Every key is optional; the defaults below\n"
        "# are the ones `bioguard init` chose for this corpus.\n"
        "#\n"
        "# access   which threat models this deployment faces.\n"
        "#          insert    = records can only be submitted for acceptance\n"
        "#          overwrite = records already in the corpus can be edited\n"
        "# budget   the fraction of genuine records a layer may sacrifice. Every\n"
        "#          threshold is derived from this by `bioguard calibrate`, never\n"
        "#          from a constant.\n"
        "# policy   permissive | balanced | strict -- how findings become verdicts.\n"
        "# vote     query-time policy. donor_cap, weight and abstain exist ONLY\n"
        "#          here; they have no ingest-time form.\n"
        "#\n"
        "# `bioguard explain <layer>` prints what each layer catches and misses.\n\n"
    )
    return header + body
